/// <summary>
/// PricingAttribute of table <c>CustTable</c> field LineOfBusinessId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, LineOfBusinessId))]
internal class GUPPricingAttributeCustTableLineOfBusinessId extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, LineOfBusinessId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    CustTable       custTable;
    LineOfBusiness  lineOfBusiness;

    while select LineOfBusinessId from custtable
        group by LineOfBusinessId
        join lineOfBusiness
        group by LineOfBusinessId, Description
        where custTable.LineOfBusinessId == lineOfBusiness.LineOfBusinessId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(lineOfBusiness.LineOfBusinessId, lineOfBusiness.Description);
        ret.add(valueObject);
    }
    return ret;
}
